    IModelDoc2 RebuildParameterAssembly(double value){
        string path=OwnedPath(parameterPath,"slider_parameter");foreach(IModelDoc2 old in Sw.GetDocuments() as object[]??new object[0])if(old.GetPathName().Equals(path,StringComparison.OrdinalIgnoreCase))Sw.CloseDoc(old.GetTitle());
