    public object SetParameter(string name,double value){
        if(name!="obstacle_x_mm"||double.IsNaN(value)||double.IsInfinity(value)||value<40||value>160)throw new Exception("PARAMETER_OUTSIDE_WHITELIST");if(parameterPath==null)throw new Exception("EXPERIMENT_NOT_REGISTERED");
        var cp=(Dictionary<string,object>)Json.DeserializeObject(Json.Serialize(CreateCheckpoint()));string checkpoint=(string)cp["checkpoint_id"];var previous=(IModelDoc2)Sw.ActiveDoc;string priorPath=previous==null?null:previous.GetPathName(),priorTitle=previous==null?null:previous.GetTitle();LastOperationRestoration="pending";
        try{ConfigureModel("parameter_trial");RebuildParameterAssembly(value);parameterValueMm=value;parameterVersion++;SaveRegistrations();LastOperationRestoration="restored";return new{parameter=name,instance="obstacle-1",value_mm=value,version=parameterVersion,results_invalidated=true,rollback_checkpoint_id=checkpoint,method="rebuild_registered_fixture_assembly_with_identical_parts_seven_mates_and_motor",restoration_status="restored"};}
        catch{try{RestoreCheckpoint(checkpoint);}catch{LastOperationRestoration="unknown";throw new Exception("PARAMETER_ROLLBACK_FAILED");}throw;}
        finally{if(priorPath!=null&&!priorPath.Equals(parameterPath,StringComparison.OrdinalIgnoreCase)){int e=0;if(Sw.ActivateDoc3(priorTitle,false,0,ref e)==null||e!=0){LastOperationRestoration="unknown";throw new Exception("PRIOR_DOCUMENT_RESTORE_FAILED");}}}
    }
    public object ParameterSearch(int maxTrials,double timeBudget){if(maxTrials<1||maxTrials>4||double.IsNaN(timeBudget)||double.IsInfinity(timeBudget)||timeBudget<=0||timeBudget>300)throw new Exception("SEARCH_BUDGET_REJECTED");var cp=(Dictionary<string,object>)Json.DeserializeObject(Json.Serialize(CreateCheckpoint()));string initial=(string)cp["checkpoint_id"];var trials=new List<object>();var timer=Stopwatch.StartNew();string winner=null,reason="trial_budget";var candidates=new[]{65.0,90,115,140};
        try{for(int i=0;i<maxTrials;i++){if(timer.Elapsed.TotalSeconds>timeBudget){reason="time_budget";break;}Progress(activeJobId,"parameter_search",i,maxTrials,null);SetParameter("obstacle_x_mm",candidates[i]);string run=Guid.NewGuid().ToString("N");Solve("parameter_trial","MVP_60rpm",1,30,run);var result=FastCheck(run,1,.001,null);var scan=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(reports[run]));trials.Add(new{trial=i,parameter="obstacle_x_mm",value_mm=candidates[i],run_id=run,scan=result,elapsed_s=timer.Elapsed.TotalSeconds});if((string)scan["assertion"]=="pass"){winner=run;reason="first_feasible_sampled_candidate";break;}}if(winner==null)RestoreCheckpoint(initial);}
        catch{RestoreCheckpoint(initial);throw;}
        string output=Path.Combine(Path.GetDirectoryName(parameterPath),"parameter-search-"+Guid.NewGuid().ToString("N")+".json");var summary=new{parameter="obstacle_x_mm",trials=trials,winner_run_id=winner,assertion=winner==null?"inconclusive":"pass",scope="registered_slider_crank_with_three_declared_joint_exclusions",claim="31_discrete_solver_frames_only",optimality_claim=false,continuous_collision=false,stop_reason=reason,initial_checkpoint_id=initial,elapsed_s=timer.Elapsed.TotalSeconds,time_budget_s=timeBudget,budget_boundary="between_trials; an active COM call is not forcibly cancelled",restoration_status=winner==null?"restored":"verified_candidate_retained",report_path=output};AtomicJson(output,summary);return summary;
    }
    public object EventDetail(string id,string eventId,bool locate){var r=GetRun(id);string path;if(!reports.TryGetValue(id,out path))throw new Exception("INTERFERENCE_REPORT_NOT_FOUND");var report=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));var items=((System.Collections.IEnumerable)report["events"]).Cast<Dictionary<string,object>>();var hit=items.SingleOrDefault(v=>(string)v["event_id"]==eventId);if(hit==null)throw new Exception("EVENT_NOT_FOUND_IN_LATEST_REPORT");var s=new Scope(this,r.Path,r.Study);double delta=0;string image=null;IModelView view=null;object orientation=null,translation=null;double scale=0;Dictionary<IComponent2,int> visibility=null;Dictionary<int,bool> displayOptions=null;
        try{ValidateRun(r,s);if(locate){if(((ISelectionMgr)s.Doc.SelectionManager).GetSelectedObjectCount2(-1)!=0)throw new Exception("EVENT_SELECTION_NOT_EMPTY");int frame=Convert.ToInt32(hit["frame"]);s.Study.SetTime(Argument(r.Times[frame],r.Duration));Application.DoEvents();delta=Transforms(s.Doc).Max(p=>p.Value.Zip(r.Poses[p.Key][frame],(a,b)=>Math.Abs(a-b)).Max());if(delta>1e-7)throw new Exception("POSE_MISMATCH");view=(IModelView)s.Doc.ActiveView;orientation=view.Orientation3;translation=view.Translation3;scale=view.Scale2;displayOptions=new[]{(int)swUserPreferenceToggle_e.swDisplayPlanes,(int)swUserPreferenceToggle_e.swDisplayAxes,(int)swUserPreferenceToggle_e.swDisplayTemporaryAxes,(int)swUserPreferenceToggle_e.swDisplayOrigins,(int)swUserPreferenceToggle_e.swDisplayCoordSystems}.ToDictionary(k=>k,k=>s.Doc.GetUserPreferenceToggle(k));foreach(var p in displayOptions)if(!s.Doc.SetUserPreferenceToggle(p.Key,false))throw new Exception("EVENT_DISPLAY_OPTION_FAILED");visibility=((object[])((IAssemblyDoc)s.Doc).GetComponents(false)).Cast<IComponent2>().ToDictionary(c=>c,c=>c.Visible);var names=((System.Collections.IEnumerable)hit["parts"]).Cast<string>().ToArray();foreach(var c in visibility.Keys)c.Visible=names.Contains(c.Name2)?1:0;s.Doc.ClearSelection2(true);foreach(var c in visibility.Keys.Where(c=>names.Contains(c.Name2)))c.Select4(true,null,false);s.Doc.ShowNamedView2("*Isometric",-1);s.Doc.ViewZoomToSelection();s.Doc.GraphicsRedraw2();image=Path.Combine(r.Directory,"事件定位_"+Regex.Replace(eventId,"[^a-zA-Z0-9_]","_")+".bmp");if(!s.Doc.SaveBMP(image,1200,900)||!File.Exists(image))throw new Exception("EVENT_IMAGE_EXPORT_FAILED");}}
        finally{try{if(displayOptions!=null)foreach(var p in displayOptions)s.Doc.SetUserPreferenceToggle(p.Key,p.Value);if(visibility!=null)foreach(var p in visibility)p.Key.Visible=p.Value;if(view!=null){view.Orientation3=(MathTransform)orientation;view.Translation3=(MathVector)translation;view.Scale2=scale;s.Doc.ClearSelection2(true);s.Doc.GraphicsRedraw2();}}finally{s.Dispose();}}
        return new{run_id=id,event_id=eventId,event_detail=hit,report_path=path,report_sha256=FileHash(path),image_path=image,maximum_pose_difference=delta,restoration_status="restored",event_identity_scope="latest_check_report_for_this_run"};
    }
